source('mp10_immune_endothelial_mechanisms_v1/scripts/common.R');plan<-rd('model_plan.tsv');ac<-rd('activity_associations.tsv.gz');all<-list()
for(lin in c('Epi','T_lineage','Endothelial'))for(mask in if(lin=='Epi')c('Full','M20-masked')else'Full'){
 stem<-if(mask=='Full')lin else paste0(lin,'_',mask);f<-tb(paste0('scenic_',stem,'_associations.tsv.gz'));if(!file.exists(f))next;z<-fread(f);cov<-rd(paste0('scenic_',stem,'_regulon_coverage.tsv'));z<-merge(z,cov[,.(regulon,TF,n_targets,n_covered_targets,small_regulon)],by='regulon');all[[stem]]<-z
}
z<-rbindlist(all,fill=TRUE);if(!nrow(z))stop('No SCENIC results');z[,joint_main_q:=NA_real_];for(kk in c('Epi','receiver')){ix<-which(z$mask=='Full'&z$model_id%in%plan[primary&kind==kk,model_id]);z[ix,joint_main_q:=p.adjust(sample_model_p,'BH')]};put(z,'scenic_all_associations.tsv.gz')
# Cross-network effects are not standardized to numerical equality.
w<-merge(z,plan,by='model_id');ct<-ac[resource=='CollecTRI',.(model_id,mask,TF=source,CollecTRI_effect=activity_effect,CollecTRI_p=sample_model_p,CollecTRI_q=sample_model_q)];dr<-ac[resource=='DoRothEA_AB',.(model_id,mask,TF=source,DoRothEA_effect=activity_effect,DoRothEA_p=sample_model_p,DoRothEA_q=sample_model_q)];w<-merge(w,ct,by=c('model_id','mask','TF'),all=TRUE);w<-merge(w,dr,by=c('model_id','mask','TF'),all=TRUE);for(nm in setdiff(names(plan),'model_id'))w[,(nm):=plan[[nm]][match(model_id,plan$model_id)]];w[,same_direction_CollecTRI:=sign(AUCell_effect)==sign(CollecTRI_effect)];w[,same_direction_DoRothEA:=sign(AUCell_effect)==sign(DoRothEA_effect)];tfs<-sort(unique(c(z$TF,ac[resource%in%c('CollecTRI','DoRothEA_AB'),source])));feat<-rd('feature_universe.tsv.gz')$gene;rnlist<-list();for(mid in unique(c(z$model_id,ac$model_id))){dd<-rd(paste0('de/',mid,'.tsv.gz'));rr<-merge(data.table(source=tfs),dd,by.x='source',by.y='gene',all.x=TRUE);rr[,`:=`(model_id=mid,rna_status=ifelse(!source%in%feat,'feature_absent',ifelse(is.na(PValue),'expression_filtered','tested')))];rnlist[[mid]]<-rr};rna<-rbindlist(rnlist,fill=TRUE);put(rna,'TF_RNA_de_all_networks.tsv.gz');rna<-unique(rna[,.(model_id,TF=source,RNA_logFC=logFC,RNA_p=PValue,RNA_q=FDR,RNA_status=rna_status)]);w<-merge(w,rna,by=c('model_id','TF'),all.x=TRUE);put(w,'TF_RNA_cross_network_comparison.tsv.gz')
# Descriptive shared target evidence with explicit target DE and TF-model quantities.
links<-rd('nichenet_target_links.tsv.gz');net<-fread(file.path(REF,'collectri.tsv'));setnames(net,'source','TF');out<-list();regsets<-list(CollecTRI=unique(net[,.(TF,target,mor)]));for(lin in c('Epi','T_lineage','Endothelial')){ee<-rd(paste0('scenic_',lin,'_regulon_edges.tsv.gz'));regsets[[paste0('SCENIC_',lin)]]<-unique(ee[TF!=target,.(TF,target,mor=NA_real_)])}
for(id in plan[primary==TRUE,model_id]){p<-plan[model_id==id];maskval<-if(p$kind=='Epi')'M20-masked'else'Full';ll<-links[model_id==id&mask==maskval&target_direction=='union'&prior_weight>0];if(!nrow(ll))next;keys<-ac[model_id==id&resource=='CollecTRI'&mask==maskval][order(sample_model_q,source),head(source,10)];lin<-if(p$kind=='Epi')'Epi'else if(p$target%in%c('Treg','Tfh/CXCL13-like'))'T_lineage'else'Endothelial'
 for(resource in c('CollecTRI',paste0('SCENIC_',lin))){nn<-regsets[[resource]][TF%in%keys];v<-merge(ll,nn,by='target',allow.cartesian=TRUE);v[,`:=`(regulatory_resource=resource,interpretation='shared target support; no inferred ligand-to-TF causal edge')];out[[paste(id,resource)]]<-v}
};put(rbindlist(out,fill=TRUE),'ligand_TF_shared_actual_targets.tsv.gz')
# NicheNet sensitivity retains rank changes and low-information flags without a winner score.
n<-merge(rd('nichenet_ligand_activities.tsv.gz'),plan,by='model_id');main<-n[primary&detection_threshold==.1&mask==ifelse(kind=='Epi','M20-masked','Full'),.(kind,target,target_direction,test_ligand,main_rank_agnostic=rank_sender_agnostic,main_rank_focused=rank_focused,main_aupr=aupr_corrected)];n<-merge(n,main,by=c('kind','target','target_direction','test_ligand'),all.x=TRUE);n[,`:=`(rank_change_focused=rank_focused-main_rank_focused,constant_prior_prediction=is.na(pearson))];n[,rank_variable_prior_agnostic:=NA_integer_];n[,rank_variable_prior_focused:=NA_integer_];n[constant_prior_prediction==FALSE,rank_variable_prior_agnostic:=frank(-aupr_corrected,ties.method='min'),by=.(model_id,mask,target_direction,detection_threshold)];n[constant_prior_prediction==FALSE&!is.na(rank_focused),rank_variable_prior_focused:=frank(-aupr_corrected,ties.method='min'),by=.(model_id,mask,target_direction,detection_threshold)];put(n,'nichenet_sensitivity_ranks.tsv.gz')
# Add direct TF/shared-target fields to the full unweighted candidate evidence table.
e<-rd('complete_candidate_evidence.tsv.gz');oldcols<-intersect(c('n_shared_actual_targets','shared_actual_targets','shared_TFs','shared_resources'),names(e));if(length(oldcols))e[,(oldcols):=NULL];ov<-rbindlist(out,fill=TRUE);if(nrow(ov)){summ<-ov[direction=='Epi_to_TME',.(n_shared_actual_targets=uniqueN(target),shared_actual_targets=paste(sort(unique(target)),collapse=';'),shared_TFs=paste(sort(unique(TF)),collapse=';'),shared_resources=paste(sort(unique(regulatory_resource)),collapse=';')),by=.(receiver,ligand)];e<-merge(e,summ,by=c('receiver','ligand'),all.x=TRUE)};for(r in unique(e$receiver)){id<-plan[primary&kind=='receiver'&target==r,model_id];s<-z[model_id==id&mask=='Full'];e[receiver==r,`:=`(receiver_SCENIC_tested=if(nrow(s))nrow(s)else NA_integer_,receiver_SCENIC_q05=if(nrow(s))sum(s$sample_model_q<.05)else NA_integer_)]};put(e,'complete_candidate_evidence.tsv.gz');cat('REGULATORY INTEGRATION COMPLETE\n')
